import os
import re
from datetime import datetime, date
import openpyxl
from openpyxl.utils.datetime import from_excel

input_path = "/mnt/data/spreadsheet/57090/1_57090_input.xlsx"
output_path = "/mnt/data/outputs/57090_0_c78b0e22/1_57090_output.xlsx"

wb = openpyxl.load_workbook(input_path)
ws = wb["Sheet1"]

def project_key(value):
    """Normalize project IDs so repeated numeric IDs compare consistently."""
    if value is None:
        return None
    if isinstance(value, float) and value.is_integer():
        return int(value)
    return value

def shipped_year(value):
    """Extract a year from the shipped-date cell."""
    if value is None:
        return None
    if isinstance(value, datetime):
        return value.year
    if isinstance(value, date):
        return value.year
    if isinstance(value, (int, float)):
        try:
            return from_excel(value).year
        except Exception:
            return int(value) if 1900 <= int(value) <= 9999 else None
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return None
        match = re.search(r"(19|20)\d{2}", text)
        if match:
            return int(match.group(0))
        try:
            return datetime.fromisoformat(text).year
        except Exception:
            return None
    return None

# Build a mapping of shipped year -> unique project IDs.
projects_by_year = {}
for row in range(2, ws.max_row + 1):
    pid = project_key(ws.cell(row=row, column=2).value)  # Project ID column B
    yr = shipped_year(ws.cell(row=row, column=3).value)  # Shipped column C
    if pid is not None and yr is not None:
        projects_by_year.setdefault(yr, set()).add(pid)

def header_year(value):
    """Extract the intended year from header cells."""
    if value is None:
        return None
    if isinstance(value, datetime):
        return value.year
    if isinstance(value, date):
        return value.year
    if isinstance(value, (int, float)):
        return int(value)
    if isinstance(value, str):
        match = re.search(r"\d+", value)
        return int(match.group(0)) if match else None
    return None

# Fill only G2:K2 with the unique project counts for the years shown in G1:K1.
previous_year = None
for col in range(7, 12):  # G:K
    yr = header_year(ws.cell(row=1, column=col).value)

    # If a year header is malformed/truncated (e.g., "221" after 2020), infer the next year.
    if yr is None or yr < 1000:
        if previous_year is not None:
            yr = previous_year + 1

    ws.cell(row=2, column=col).value = len(projects_by_year.get(yr, set())) if yr is not None else 0

    if yr is not None and yr >= 1000:
        previous_year = yr

os.makedirs(os.path.dirname(output_path), exist_ok=True)
wb.save(output_path)
